import bpy

# Get or reuse the stool wood material
mat = bpy.data.materials.get("Mat_Stool_Wood")

for direction in ['N', 'E', 'S', 'W']:
    for i in range(1, 5):
        name = f"Stool_Leg_{direction}_{i}"
        obj = bpy.data.objects.get(name)
        if obj:
            obj.data.materials.clear()
            obj.data.materials.append(mat)

import bpy

for direction in ['N', 'E', 'S', 'W']:
    seat = bpy.data.objects.get(f"Stool_Seat_{direction}")
    if seat:
        for i in range(1, 5):
            leg = bpy.data.objects.get(f"Stool_Leg_{direction}_{i}")
            if leg:
                leg.parent = seat
                leg.matrix_parent_inverse = seat.matrix_world.inverted()

import bpy

# Smooth shade all bottle parts
bottle_parts = ['Bottle_Body', 'Bottle_Neck', 'Bottle_Lip', 'Bottle_Shoulder']
for part_name in bottle_parts:
    obj = bpy.data.objects.get(part_name)
    if obj:
        bpy.ops.object.select_all(action='DESELECT')
        obj.select_set(True)
        bpy.context.view_layer.objects.active = obj
        bpy.ops.object.shade_smooth()

# Ensure viewport is set to material preview
for area in bpy.context.screen.areas:
    if area.type == 'VIEW_3D':
        for space in area.spaces:
            if space.type == 'VIEW_3D':
                space.shading.type = 'MATERIAL'
                break
